data:
/* 大河の一滴 — UIはできるだけ少なくする。世界を見るゲームだから。 */

.scene,
.title,
.intro,
.game,
.summary,
.records {
  --serif: "Hiragino Mincho ProN", "Yu Mincho", "Noto Serif JP", serif;
  --sans: -apple-system, "Hiragino Kaku Gothic ProN", "Noto Sans JP", Meiryo, sans-serif;
  --ink: #f2f7fb;
  --dim: rgb(242 247 251 / 62%);
  --glass: rgb(8 14 22 / 52%);
  --line: rgb(242 247 251 / 16%);
}

/* ───────────── 場面：後景 / プレイ層 / 前景 ───────────── */

.scene {
  position: absolute;
  inset: 0;
  overflow: hidden;
}

.layerBack,
.layerFront {
  position: absolute;
  inset: -6%;
  width: 112%;
  height: 112%;
}

.layerBack {
  transform: scale(1.02);
  opacity: 0.92;
}

.layerHaze {
  position: absolute;
  inset: 0;
  opacity: 0.14;
  mix-blend-mode: screen;
  pointer-events: none;
}

.layerFront {
  transform: scale(1.16) translateY(2%);
}

.vignette {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(120% 78% at 50% 42%, rgb(0 0 0 / 0%) 42%, rgb(0 0 0 / 46%) 100%),
    linear-gradient(to bottom, rgb(0 0 0 / 24%) 0%, rgb(0 0 0 / 0%) 26%);
  pointer-events: none;
}

/* 場面の動き */
.driftSlow {
  animation: driftX 64s linear infinite;
}

.driftVerySlow {
  animation: driftX 140s linear infinite;
}

.swayLeaf {
  transform-origin: 50% 0;
  animation: sway 11s ease-in-out infinite;
}

.swaySlow {
  transform-origin: 50% 100%;
  animation: sway 8s ease-in-out infinite;
}

.flowWave {
  animation: waveShift 9s ease-in-out infinite;
}

.caustics {
  animation: causticShift 14s ease-in-out infinite;
}

.rise {
  animation: riseUp 13s linear infinite;
}

.swimSlow {
  animation: swim 26s ease-in-out infinite;
}

.fallFast {
  animation: fallDown 1.4s linear infinite;
}

.fallSlow {
  animation: fallDown 9s linear infinite;
}

.floatSlow {
  animation: floatAbout 18s ease-in-out infinite;
}

.rayShift {
  animation: rayMove 20s ease-in-out infinite;
}

@keyframes driftX {
  from { transform: translateX(-8%); }
  to { transform: translateX(8%); }
}

@keyframes sway {
  0%, 100% { transform: rotate(-1.1deg); }
  50% { transform: rotate(1.1deg); }
}

@keyframes waveShift {
  0%, 100% { transform: translateX(-3%) translateY(0); }
  50% { transform: translateX(3%) translateY(-1.5%); }
}

@keyframes causticShift {
  0%, 100% { transform: translateX(-4%) skewX(-3deg); opacity: 0.32; }
  50% { transform: translateX(4%) skewX(3deg); opacity: 0.5; }
}

@keyframes riseUp {
  from { transform: translateY(14%); }
  to { transform: translateY(-24%); }
}

@keyframes swim {
  0%, 100% { transform: translateX(-14%); }
  50% { transform: translateX(14%); }
}

@keyframes fallDown {
  from { transform: translateY(-18%); }
  to { transform: translateY(18%); }
}

@keyframes floatAbout {
  0%, 100% { transform: translate(-3%, 2%); }
  50% { transform: translate(3%, -3%); }
}

@keyframes rayMove {
  0%, 100% { transform: translateX(-3%); opacity: 0.24; }
  50% { transform: translateX(3%); opacity: 0.38; }
}

/* ───────────── 水そのもの ───────────── */

.dropWrap {
  position: relative;
  width: 128px;
  height: 128px;
  display: grid;
  place-items: center;
  transform: scale(var(--dropScale, 1));
  pointer-events: none;
}

.dropHalo {
  position: absolute;
  width: 260%;
  height: 260%;
  border-radius: 50%;
  background: radial-gradient(circle, var(--glow) 0%, rgb(255 255 255 / 0%) 62%);
  opacity: 0.34;
  animation: breathe 5.5s ease-in-out infinite;
}

.dropCore {
  position: absolute;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 18px 6px var(--glow), 0 0 44px 14px var(--glow);
  animation: pulse 3.4s ease-in-out infinite;
}

.dropLiquid {
  position: relative;
  width: 92px;
  height: 92px;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at 34% 28%, rgb(255 255 255 / 62%) 0%, rgb(255 255 255 / 8%) 34%, rgb(255 255 255 / 0%) 60%),
    radial-gradient(circle at 62% 74%, var(--glow) 0%, rgb(255 255 255 / 6%) 72%);
  border: 1px solid rgb(255 255 255 / 42%);
  border-radius: 52% 48% 46% 54% / 55% 52% 48% 45%;
  box-shadow:
    inset 0 -8px 22px rgb(255 255 255 / 26%),
    inset 0 8px 18px rgb(255 255 255 / 14%),
    0 0 40px rgb(255 255 255 / 18%);
  backdrop-filter: blur(1px);
  animation: wobble 6.5s ease-in-out infinite;
}

.dropSheen {
  position: absolute;
  top: 16%;
  left: 22%;
  width: 26%;
  height: 18%;
  border-radius: 50%;
  background: rgb(255 255 255 / 78%);
  filter: blur(1.5px);
}

.dropSolid {
  position: relative;
  width: 104px;
  height: 104px;
  display: grid;
  place-items: center;
  animation: shimmer 7s ease-in-out infinite;
}

.dropSolid svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.crystalBody {
  fill: rgb(255 255 255 / 20%);
  stroke: none;
}

.crystalEdge {
  fill: none;
  stroke: rgb(255 255 255 / 72%);
  stroke-width: 1.6;
}

.crystalCracks {
  fill: none;
  stroke: rgb(255 255 255 / 40%);
  stroke-width: 0.9;
}

.dropGas {
  position: relative;
  width: 120px;
  height: 120px;
  display: grid;
  place-items: center;
}

.gasDot {
  position: absolute;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--glow);
  filter: blur(2px);
  opacity: 0.6;
  animation: gasFloat 4.6s ease-in-out infinite;
  animation-delay: calc(var(--i) * -0.52s);
  transform-origin: 50% 50%;
}

.gasDot:nth-child(odd) { width: 6px; height: 6px; }
.gasDot:nth-child(1) { translate: -30px 18px; }
.gasDot:nth-child(2) { translate: 22px -14px; }
.gasDot:nth-child(3) { translate: -8px -30px; }
.gasDot:nth-child(4) { translate: 34px 22px; }
.gasDot:nth-child(5) { translate: -34px -8px; }
.gasDot:nth-child(6) { translate: 10px 32px; }
.gasDot:nth-child(7) { translate: -20px 34px; }
.gasDot:nth-child(8) { translate: 30px -30px; }
.gasDot:nth-child(9) { translate: 0 0; }

@keyframes wobble {
  0%, 100% { border-radius: 52% 48% 46% 54% / 55% 52% 48% 45%; transform: rotate(0deg) scale(1); }
  33% { border-radius: 46% 54% 55% 45% / 48% 46% 54% 52%; transform: rotate(3deg) scale(1.03); }
  66% { border-radius: 55% 45% 48% 52% / 46% 55% 45% 54%; transform: rotate(-3deg) scale(0.98); }
}

@keyframes breathe {
  0%, 100% { opacity: 0.28; transform: scale(1); }
  50% { opacity: 0.46; transform: scale(1.1); }
}

@keyframes pulse {
  0%, 100% { opacity: 0.86; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.16); }
}

@keyframes shimmer {
  0%, 100% { opacity: 0.86; transform: rotate(-1deg); }
  50% { opacity: 1; transform: rotate(1deg); }
}

@keyframes gasFloat {
  0%, 100% { opacity: 0.24; scale: 0.7; }
  50% { opacity: 0.72; scale: 1.2; }
}

/* ───────────── タイトル ───────────── */

.title {
  position: fixed;
  inset: 0;
  overflow-y: auto;
  background: #0a1420;
  color: var(--ink);
  font-family: var(--sans);
}

.titleInner {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  min-height: 100%;
  padding: 56px 26px 44px;
  text-align: center;
  background: linear-gradient(to bottom, rgb(6 12 20 / 8%) 0%, rgb(6 12 20 / 42%) 42%, rgb(6 12 20 / 84%) 100%);
}

.titleEyebrow {
  margin: 0;
  color: var(--dim);
  font-size: 12px;
  letter-spacing: 0.22em;
}

.titleMain {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(46px, 15vw, 74px);
  font-weight: 400;
  letter-spacing: 0.06em;
  line-height: 1.14;
  text-shadow: 0 2px 30px rgb(0 0 0 / 60%);
}

.titleMain span {
  color: #bfeaff;
}

.titleLead {
  max-width: 30em;
  margin: 0;
  color: var(--dim);
  font-family: var(--serif);
  font-size: 14px;
  line-height: 2.1;
}

.titleNote {
  margin: 4px 0 8px;
  color: #bfeaff;
  font-size: 13px;
  letter-spacing: 0.1em;
}

.titleActions {
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: min(340px, 100%);
}

.titleProfile {
  max-width: 26em;
  margin: 6px 0 0;
  color: var(--dim);
  font-family: var(--serif);
  font-size: 12.5px;
  line-height: 1.9;
}

/* ボタン */

.primaryBtn,
.ghostBtn,
.endingBtn {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 15px 22px;
  border: 1px solid rgb(255 255 255 / 34%);
  border-radius: 999px;
  background: rgb(255 255 255 / 12%);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 15px;
  letter-spacing: 0.08em;
  cursor: pointer;
  backdrop-filter: blur(8px);
  transition: background 0.2s ease, transform 0.2s ease;
}

.primaryBtn {
  border-color: rgb(191 234 255 / 62%);
  background: rgb(191 234 255 / 20%);
}

.primaryBtn small,
.ghostBtn small {
  color: var(--dim);
  font-size: 11px;
  letter-spacing: 0.14em;
}

.primaryBtn:hover,
.ghostBtn:hover,
.endingBtn:hover {
  background: rgb(255 255 255 / 22%);
  transform: translateY(-1px);
}

.quietBtn {
  padding: 10px 6px;
  border: 0;
  background: none;
  color: var(--dim);
  font-family: var(--sans);
  font-size: 11.5px;
  letter-spacing: 0.08em;
  line-height: 1.8;
  text-decoration: underline;
  text-underline-offset: 4px;
  cursor: pointer;
}

.dangerBtn {
  padding: 10px 20px;
  border: 1px solid rgb(255 150 150 / 50%);
  border-radius: 999px;
  background: rgb(255 120 120 / 16%);
  color: #ffd6d6;
  font-family: var(--sans);
  font-size: 13px;
  cursor: pointer;
}

/* ───────────── 導入 ───────────── */

.intro {
  position: fixed;
  inset: 0;
  display: block;
  width: 100%;
  padding: 0;
  border: 0;
  background: #0a1420;
  color: var(--ink);
  font-family: var(--sans);
  text-align: center;
  cursor: pointer;
}

.introZoom {
  position: absolute;
  top: 42%;
  left: 50%;
  z-index: 2;
  translate: -50% -50%;
  transition: scale 2s ease-out;
}

.introZoom[data-step="0"] { scale: 0.5; }
.introZoom[data-step="1"] { scale: 0.8; }
.introZoom[data-step="2"] { scale: 1.05; }
.introZoom[data-step="3"] { scale: 1.2; }

.introText {
  position: absolute;
  right: 0;
  bottom: 12%;
  left: 0;
  z-index: 3;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 0 26px;
}

.introLine,
.introYou,
.introHint {
  margin: 0;
  animation: fadeUp 1.4s ease both;
}

.introLine {
  color: var(--dim);
  font-family: var(--serif);
  font-size: 15px;
}

.introYou {
  color: var(--ink);
  font-family: var(--serif);
  font-size: 24px;
  letter-spacing: 0.14em;
  text-shadow: 0 0 24px rgb(191 234 255 / 60%);
}

.introHint {
  color: var(--dim);
  font-size: 11px;
  letter-spacing: 0.2em;
  animation: fadeBlink 2.4s ease-in-out infinite;
}

/* ───────────── プレイ画面 ───────────── */

.game {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #060b12;
  color: var(--ink);
  font-family: var(--sans);
}

.sceneHolder {
  position: absolute;
  inset: 0;
  animation: sceneIn 1.1s ease both;
}

.playLayer {
  position: absolute;
  top: 40%;
  left: 50%;
  z-index: 2;
  translate: -50% -50%;
  animation: dropIn 1.2s ease both;
}

.hud {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  z-index: 4;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: max(14px, env(safe-area-inset-top)) 18px 18px;
  background: linear-gradient(to bottom, rgb(4 8 14 / 62%), rgb(4 8 14 / 0%));
  pointer-events: none;
}

.hudLeft,
.hudRight {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.hudRight {
  align-items: flex-end;
}

.hudPlace {
  color: var(--dim);
  font-size: 10.5px;
  letter-spacing: 0.16em;
}

.hudNode {
  font-family: var(--serif);
  font-size: 17px;
  letter-spacing: 0.06em;
}

.hudPhase {
  padding: 2px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 10px;
  letter-spacing: 0.16em;
}

.hudPhase[data-phase="solid"] { color: #cdeaff; border-color: rgb(205 234 255 / 46%); }
.hudPhase[data-phase="gas"] { color: #e0d6ff; border-color: rgb(224 214 255 / 40%); }

.hudTime {
  color: var(--dim);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.08em;
}

.corner {
  position: absolute;
  top: max(58px, calc(env(safe-area-inset-top) + 48px));
  right: 18px;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 7px;
}

.iconBtn {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: rgb(6 12 20 / 44%);
  color: var(--dim);
  cursor: pointer;
  backdrop-filter: blur(6px);
  transition: color 0.2s ease, border-color 0.2s ease;
}

.iconBtn:hover {
  border-color: rgb(191 234 255 / 50%);
  color: var(--ink);
}

.soundToggle {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 16px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: none;
  color: var(--dim);
  font-family: var(--sans);
  font-size: 11.5px;
  letter-spacing: 0.1em;
  cursor: pointer;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.soundToggle:hover {
  border-color: rgb(191 234 255 / 50%);
  color: var(--ink);
}

.recordsLink {
  padding: 5px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgb(6 12 20 / 44%);
  color: var(--dim);
  font-family: var(--sans);
  font-size: 10.5px;
  letter-spacing: 0.14em;
  cursor: pointer;
  backdrop-filter: blur(6px);
}

/* 読み終わった人が待たされないためのタップ領域 */
.tapLayer,
.tapLayerTop {
  position: absolute;
  inset: 0;
  border: 0;
  background: none;
  cursor: pointer;
}

.tapLayer {
  z-index: 3;
}

/* 行動の説明を見せている最中は、他に押すものがないので全面で受ける */
.tapLayerTop {
  z-index: 6;
}

/* 下部パネル */

.panel {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 4;
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-height: 68%;
  overflow-y: auto;
  padding: 40px 18px calc(18px + env(safe-area-inset-bottom));
  background: linear-gradient(to bottom, rgb(4 8 14 / 0%) 0%, rgb(4 8 14 / 74%) 22%, rgb(4 8 14 / 92%) 100%);
}

/* TIME FLOW 中は何もできない。選択肢も引っ込める。 */
.panel[data-hidden="true"] {
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.9s ease;
}

.lines {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.lines p {
  margin: 0;
  font-family: var(--serif);
  font-size: 15px;
  line-height: 1.95;
  text-shadow: 0 1px 12px rgb(0 0 0 / 70%);
  animation: fadeUp 0.9s ease both;
}

.reaction {
  margin: 0;
  padding: 14px 2px;
  color: #bfeaff;
  font-family: var(--serif);
  font-size: 15px;
  line-height: 1.9;
  animation: fadeUp 0.5s ease both;
}

.choices {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 2px;
}

.choice {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 13px 16px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--glass);
  color: var(--ink);
  font-family: var(--sans);
  text-align: left;
  cursor: pointer;
  backdrop-filter: blur(10px);
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
  animation: fadeUp 0.6s ease both;
}

.choice strong {
  font-family: var(--serif);
  font-size: 15.5px;
  font-weight: 400;
  letter-spacing: 0.04em;
}

.choice span {
  color: var(--dim);
  font-size: 12px;
  line-height: 1.7;
}

.choice:hover:not(:disabled) {
  border-color: rgb(191 234 255 / 56%);
  background: rgb(20 40 60 / 68%);
  transform: translateY(-1px);
}

.choice:disabled {
  cursor: default;
  opacity: 0.55;
}

.driftBtn {
  padding: 11px;
  border: 1px dashed var(--line);
  border-radius: 999px;
  background: none;
  color: var(--dim);
  font-family: var(--sans);
  font-size: 12.5px;
  letter-spacing: 0.14em;
  cursor: pointer;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.driftBtn:hover:not(:disabled) {
  border-color: rgb(191 234 255 / 50%);
  color: var(--ink);
}

.driftBtn:disabled {
  cursor: default;
  opacity: 0.4;
}

.endingBtn {
  align-items: center;
}

.driftNote {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin: 0;
  color: var(--dim);
  font-size: 11.5px;
  letter-spacing: 0.1em;
}

.driftNote button {
  padding: 5px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: none;
  color: var(--ink);
  font-family: var(--sans);
  font-size: 11px;
  cursor: pointer;
}

/* ───────────── TIME FLOW ───────────── */

.timeFlow {
  position: absolute;
  inset: 0;
  z-index: 6;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  width: 100%;
  padding: 24px;
  border: 0;
  background: rgb(3 7 12 / 68%);
  color: var(--ink);
  font-family: var(--sans);
  cursor: pointer;
  backdrop-filter: blur(2px) saturate(0.7);
  animation: fadeIn 1.4s ease both;
}

.timeFlowLabel {
  color: var(--dim);
  font-size: 10.5px;
  letter-spacing: 0.42em;
}

.timeFlowTicks {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  min-height: 82px;
  justify-content: flex-end;
}

.timeFlowPast {
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.12em;
}

.timeFlowNow {
  font-family: var(--serif);
  font-size: clamp(38px, 13vw, 58px);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.06em;
  text-shadow: 0 0 40px rgb(191 234 255 / 40%);
  animation: tickIn 0.5s ease both;
}

.timeFlowChanges {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 24em;
  min-height: 60px;
  text-align: center;
}

.timeFlowChanges span {
  color: #bfeaff;
  font-family: var(--serif);
  font-size: 14px;
  line-height: 1.9;
  animation: fadeUp 1.2s ease both;
}

.timeFlowHint {
  color: var(--dim);
  font-size: 10.5px;
  letter-spacing: 0.2em;
}

/* ───────────── 旅の記録 ───────────── */

.summary {
  position: fixed;
  inset: 0;
  overflow-y: auto;
  background:
    radial-gradient(120% 60% at 50% 0%, rgb(90 160 210 / 22%) 0%, rgb(90 160 210 / 0%) 62%),
    linear-gradient(to bottom, #0e1c2b 0%, #060b12 60%);
  color: var(--ink);
  font-family: var(--sans);
}

.summaryInner {
  max-width: 620px;
  margin: 0 auto;
  padding: 52px 22px calc(48px + env(safe-area-inset-bottom));
}

.summaryEyebrow {
  margin: 0 0 8px;
  color: var(--dim);
  font-size: 11px;
  letter-spacing: 0.2em;
}

.summaryTitle {
  margin: 0 0 26px;
  font-family: var(--serif);
  font-size: 28px;
  font-weight: 400;
  letter-spacing: 0.14em;
}

.summaryLead {
  margin: 0 0 6px;
  color: var(--dim);
  font-size: 12px;
  letter-spacing: 0.14em;
}

.summaryBig {
  margin: 0 0 26px;
  font-family: var(--serif);
  font-size: clamp(30px, 9vw, 44px);
  font-variant-numeric: tabular-nums;
