  en: "英語",
  zh: "中国語",
  ja: "日本語",
};

function nowTime() {
  return new Date().toLocaleTimeString("ja-JP", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

function csvCell(value: string) {
  return `"${value.replaceAll('"', '""')}"`;
}

export default function BrowserTranslatePage() {
  const [source, setSource] = useState<SourceLanguage>("en");
  const [inputMode, setInputMode] = useState<InputMode>("mic");
  const [speakOn, setSpeakOn] = useState(false);
  const [running, setRunning] = useState(false);
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState("言語と入力元を選んで開始してください。");
  const [error, setError] = useState("");
  const [original, setOriginal] = useState("");
  const [translation, setTranslation] = useState("「開始」を押してください。");
  const [entries, setEntries] = useState<TranscriptEntry[]>([]);

  const recognitionRef = useRef<RecognitionLike | null>(null);
  const displayStreamRef = useRef<MediaStream | null>(null);
  const activeTrackRef = useRef<MediaStreamTrack | null>(null);
  const runningRef = useRef(false);
  const sourceRef = useRef<SourceLanguage>(source);

  const locale = useMemo(
    () => LANGUAGE_OPTIONS.find((item) => item.code === source)?.locale ?? "en-US",
    [source],
  );

  const stopAll = useCallback(() => {
    runningRef.current = false;
    setRunning(false);

    const recognition = recognitionRef.current;
    recognitionRef.current = null;
    if (recognition) {
      try {
        recognition.abort();
      } catch {
        // already stopped
      }
    }

    displayStreamRef.current?.getTracks().forEach((track) => track.stop());
    displayStreamRef.current = null;
    activeTrackRef.current = null;

    if (typeof window !== "undefined" && "speechSynthesis" in window) {
      window.speechSynthesis.cancel();
    }

    setBusy(false);
    setStatus("停止中。文字起こしは下のログに残っています。");
  }, []);

  const speakJapanese = useCallback((text: string) => {
    if (!speakOn || !text || typeof window === "undefined" || !("speechSynthesis" in window)) {
      return;
    }
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = "ja-JP";
    window.speechSynthesis.speak(utterance);
  }, [speakOn]);

  const handleFinal = useCallback(async (text: string) => {
    const currentSource = sourceRef.current;
    setOriginal(text);
    setTranslation(currentSource === "ja" ? "記録中…" : "翻訳中…");

    let japanese = text.trim();
    if (currentSource !== "ja") {
      const translated = await translateInBrowser(
        text,
        currentSource as LanguageCode,
        "ja" as LanguageCode,
      );
      if (!translated) {
        setTranslation(text);
        setError("翻訳できませんでした。Chromeの翻訳モデルを準備してから、もう一度話してください。");
        return;
      }
      japanese = translated;
    }

    setError("");
    setTranslation(japanese);
    setEntries((current) => [
      ...current,
      {
        id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
        time: nowTime(),
        language: LANGUAGE_NAME[currentSource],
        original: text,
        japanese,
      },
    ]);
    speakJapanese(japanese);
  }, [speakJapanese]);

  const createRecognition = useCallback((track: MediaStreamTrack | null) => {
    const scope = window as SpeechWindow;
    const Recognition = scope.SpeechRecognition ?? scope.webkitSpeechRecognition;
    if (!Recognition) {
      throw new Error("このChromeでは音声認識を利用できません。");
    }

    const recognition = new Recognition();
    recognition.lang = LANGUAGE_OPTIONS.find((item) => item.code === sourceRef.current)?.locale ?? "en-US";
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.maxAlternatives = 1;

    recognition.onresult = (event) => {
      let interim = "";
      for (let index = event.resultIndex; index < event.results.length; index += 1) {
        const result = event.results[index];
        const text = result?.[0]?.transcript?.trim() ?? "";
        if (!text) continue;
        if (result.isFinal) {
          void handleFinal(text);
        } else {
          interim += text;
        }
      }
      if (interim) setOriginal(interim);
    };

    recognition.onerror = (event) => {
      if (event.error === "no-speech" || event.error === "aborted") return;
      setError(`音声認識エラー: ${event.error}`);
    };

    recognition.onend = () => {
      if (!runningRef.current) return;
      window.setTimeout(() => {
        if (!runningRef.current) return;
        try {
          if (track && track.readyState === "live") recognition.start(track);
          else if (!track) recognition.start();
        } catch {
          // Chrome が再開準備中なら次の onend / ユーザー再開に任せる。
        }
      }, 300);
    };

    return recognition;
  }, [handleFinal]);

  const getPcAudio = useCallback(async () => {
    const options = {
      video: true,
      audio: {
        suppressLocalAudioPlayback: false,
      },
      systemAudio: "include",
      surfaceSwitching: "include",
    } as unknown as DisplayMediaStreamOptions;

    const stream = await navigator.mediaDevices.getDisplayMedia(options);
    const [audioTrack] = stream.getAudioTracks();
    if (!audioTrack) {
      stream.getTracks().forEach((track) => track.stop());
      throw new Error(
        "共有した対象に音声がありません。「タブの音声を共有」または「システム音声を共有」をONにしてください。",
      );
    }

    stream.getVideoTracks().forEach((videoTrack) => {
      videoTrack.addEventListener("ended", stopAll, { once: true });
    });
    displayStreamRef.current = stream;
    return audioTrack;
  }, [stopAll]);

  const begin = useCallback(async () => {
    if (typeof window === "undefined") return;
    setError("");
    setBusy(true);
    sourceRef.current = source;

    try {
      // Translator.create() は初回モデル準備時にユーザー操作が必要なので、
      // click ハンドラの同期区間で先にキックする。
      if (source !== "ja") {
        void prepareBrowserTranslationRoute(source as LanguageCode, "ja" as LanguageCode);
        setStatus(`${LANGUAGE_NAME[source]}→日本語の翻訳モデルを準備しています…`);
      } else {
        setStatus("日本語文字起こしを準備しています…");
      }

      const track = inputMode === "pc" ? await getPcAudio() : null;
      activeTrackRef.current = track;
      const recognition = createRecognition(track);
      recognitionRef.current = recognition;
      runningRef.current = true;
      setRunning(true);

      if (track) recognition.start(track);
      else recognition.start();

      setStatus(
        inputMode === "pc"
          ? `${LANGUAGE_NAME[source]}のPC / 会議 / YouTube音声を聞き取り中`
          : `マイクで${LANGUAGE_NAME[source]}を聞き取り中`,
      );
    } catch (caught) {
      runningRef.current = false;
      setRunning(false);
      displayStreamRef.current?.getTracks().forEach((track) => track.stop());
      displayStreamRef.current = null;
      const message = caught instanceof Error ? caught.message : String(caught);
      setError(message);
      setStatus("開始できませんでした。");
    } finally {
      setBusy(false);
    }
  }, [createRecognition, getPcAudio, inputMode, source]);

  const selectSource = (next: SourceLanguage) => {
    if (runningRef.current) stopAll();
    sourceRef.current = next;
    setSource(next);
    setOriginal("");
    setTranslation("「開始」を押してください。");
    setError("");
    setStatus(next === "ja" ? "日本語文字起こしを選択しました。" : `${LANGUAGE_NAME[next]}→日本語を選択しました。`);
  };

  const selectInput = (next: InputMode) => {
    if (runningRef.current) stopAll();
    setInputMode(next);
    setStatus(
      next === "pc"
        ? "PC / 会議 / YouTube音声を選択しました。開始後に音声が流れている対象を共有してください。"
        : "マイク入力を選択しました。",
    );
  };

  const setSpeaking = (enabled: boolean) => {
    setSpeakOn(enabled);
    if (!enabled && typeof window !== "undefined" && "speechSynthesis" in window) {
      window.speechSynthesis.cancel();
    }
    setStatus(`日本語読み上げ ${enabled ? "ON" : "OFF"}`);
  };

  const copyTranscript = async () => {
    if (!entries.length) {
      setError("コピーする文字起こしがありません。");
      return;
    }
    const text = entries
      .map((entry) =>
        entry.original === entry.japanese
          ? `[${entry.time}] ${entry.original}`
          : `[${entry.time}] ${entry.original}\n→ ${entry.japanese}`,
      )
      .join("\n\n");
    try {
      await navigator.clipboard.writeText(text);
      setError("");
      setStatus("文字起こしをコピーしました。");
    } catch {
      setError("コピーできませんでした。ブラウザのクリップボード権限を確認してください。");
    }
  };

  const downloadCsv = () => {
    if (!entries.length) {
      setError("ダウンロードする文字起こしがありません。");
      return;
    }
    const rows = [
      "時刻,言語,元の発話,日本語",
      ...entries.map((entry) =>
        [entry.time, entry.language, entry.original, entry.japanese]
          .map(csvCell)
          .join(","),
      ),
    ];
    const blob = new Blob([`\uFEFF${rows.join("\r\n")}`], {
      type: "text/csv;charset=utf-8",
    });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `digil-cloud-transcript-${new Date().toISOString().slice(0, 10)}.csv`;
    anchor.click();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <main className={styles.page}>
      <header className={styles.header}>
        <Link href="/ear-hub" className={styles.back}>‹ DIGIL CLOUD</Link>
        <span className={styles.badge}>CHROME PC</span>
      </header>

      <section className={styles.hero}>
        <p className={styles.eyebrow}>TRANSLATE / TRANSCRIBE</p>
        <h1>リアルタイム翻訳・文字起こし</h1>
        <p>マイクだけでなく、YouTube・オンライン会議・PCの共有音声をそのまま文字起こしできます。</p>
      </section>

      <section className={styles.panel}>
        <div className={styles.choiceGridThree} aria-label="言語を選択">
          {LANGUAGE_OPTIONS.map((item) => (
            <button
              key={item.code}
              type="button"
              className={`${styles.choice} ${source === item.code ? styles.active : ""}`}
              onClick={() => selectSource(item.code)}
            >
              {item.label}
            </button>
          ))}
        </div>

        <div className={styles.choiceGridTwo} aria-label="入力元を選択">
          <button
            type="button"
            className={`${styles.choice} ${inputMode === "mic" ? styles.active : ""}`}
            onClick={() => selectInput("mic")}
          >
            マイク
          </button>
          <button
            type="button"
            className={`${styles.choice} ${inputMode === "pc" ? styles.active : ""}`}
            onClick={() => selectInput("pc")}
          >
            PC / 会議 / YouTube音声
          </button>
        </div>

        <div className={styles.choiceGridTwo} aria-label="読み上げ設定">
          <button
            type="button"
            className={`${styles.choice} ${!speakOn ? styles.active : ""}`}
            onClick={() => setSpeaking(false)}
          >
            読み上げ OFF
          </button>
          <button
            type="button"
            className={`${styles.choice} ${speakOn ? styles.active : ""}`}
            onClick={() => setSpeaking(true)}
          >
            読み上げ ON
          </button>
        </div>

        <p className={styles.status}>{status}</p>

        <div className={styles.stage} aria-live="polite">
          <p className={styles.translation}>{translation}</p>
          {original ? <p className={styles.original}>{original}</p> : null}
        </div>

        <button
          type="button"
          className={`${styles.startButton} ${running ? styles.stopButton : ""}`}
          disabled={busy}
          onClick={running ? stopAll : begin}
        >
          {busy ? "準備中…" : running ? "停止" : "開始"}
        </button>

        {error ? <div className={styles.error}>{error}</div> : null}

        <div className={styles.help}>
          <strong>PC音声を使うとき：</strong> 開始後の共有画面で、音声が流れているタブ／ウィンドウ／画面を選び、
          「タブの音声を共有」または「システム音声を共有」をONにしてください。
        </div>
      </section>

      <section className={styles.panel}>
        <div className={styles.logHeader}>
          <div>
            <p className={styles.eyebrow}>TRANSCRIPT</p>
            <h2>議事録・文字起こし</h2>
          </div>
          <span>{entries.length}件</span>
        </div>

        <div className={styles.toolbar}>
          <button type="button" className={styles.primarySmall} onClick={copyTranscript}>コピー</button>
          <button type="button" className={styles.smallButton} onClick={downloadCsv}>CSVダウンロード</button>
          <button type="button" className={styles.smallButton} onClick={() => setEntries([])}>ログ消去</button>
        </div>

        <div className={styles.log}>
          {!entries.length ? (
            <p className={styles.empty}>まだ文字起こしはありません。</p>
          ) : (
            [...entries].reverse().map((entry) => (
              <article className={styles.logRow} key={entry.id}>
                <p className={styles.meta}>{entry.time} ・ {entry.language}</p>
                <p className={styles.logOriginal}>{entry.original}</p>
                {entry.original !== entry.japanese ? (
                  <p className={styles.logJapanese}>{entry.japanese}</p>
                ) : null}
              </article>
            ))
          )}
        </div>
      </section>
    </main>
  );
}

"use client";

import Link from "next/link";
import Script from "next/script";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import styles from "./ear-hub.module.css";
import { LANGUAGE_CODES, LANGUAGES, bcp47, labelOf, type LanguageCode } from "./languages";
import {
  DEFAULT_DRIVE_FOLDER,
  DEFAULT_SETTINGS,
  MODULES,
  moduleById,
  type EarHubSettings,
  type ModuleContext,
  type ModuleId,
  type SessionResult,
} from "./modules";
import {
  GOOGLE_CLIENT_ID,
  buildDocument,
  fileNameFor,
  initTokenClient,
  saveToDrive,
  type TokenClient,
} from "./drive";
import {
  Listener,
  cancelSpeech,
  isRecognitionSupported,
  primeSpeech,
  speak,
  warmUpVoices,
} from "./speech";
import {
  deleteMinutes,
  loadAccessCode,
  loadMinutes,
  loadSettings,
  saveAccessCode,
  saveMinutes,
  saveSettings,
  type SavedMinutes,
} from "./storage";

type Entry = {
  id: string;
  at: number;
  primary: string;
  secondary?: string;
  highlight?: boolean;
  status: "pending" | "done" | "error";
};

function newId() {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function clockOf(at: number) {
  return new Date(at).toLocaleTimeString("ja-JP", { hour: "2-digit", minute: "2-digit" });
}

function dateOf(at: number) {
  return new Date(at).toLocaleString("ja-JP", {
    month: "numeric",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function delay(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

type Section = { heading: string; body: string };

/** 議事録は見出し付きのMarkdownで返る。見出しと本文に分けて読みやすく出す。 */
function parseSections(markdown: string): Section[] {
  const sections: Section[] = [];
  for (const line of markdown.split("\n")) {
    const heading = /^#{1,3}\s+(.+)$/.exec(line.trim());
    if (heading) {
      sections.push({ heading: heading[1], body: "" });
      continue;
    }
    let current = sections[sections.length - 1];
    if (!current) {
      current = { heading: "", body: "" };
      sections.push(current);
    }
    current.body += current.body ? `\n${line}` : line;
  }
  return sections
    .map((section) => ({ heading: section.heading, body: section.body.trim() }))
    .filter((section) => section.heading || section.body);
}

/** 保存一覧のプレビュー用に、Markdownの記号を落とした1行を作る。 */
function previewOf(text: string) {
  const flat = text.replace(/^#+\s*/gm, "").replace(/\s+/g, " ").trim();
  return flat.length > 110 ? `${flat.slice(0, 110)}…` : flat;
}

export default function EarHub() {
  const [ready, setReady] = useState(false);
  const [supported, setSupported] = useState(true);
  const [moduleId, setModuleId] = useState<ModuleId>("translate");
  const [settings, setSettings] = useState<EarHubSettings>(DEFAULT_SETTINGS);
  const [running, setRunning] = useState(false);
  const [listening, setListening] = useState(false);
  const [speaking, setSpeaking] = useState(false);
  const [interim, setInterim] = useState("");
  const [entries, setEntries] = useState<Entry[]>([]);
  const [error, setError] = useState("");
  const [summary, setSummary] = useState<SessionResult | null>(null);
  const [summarizing, setSummarizing] = useState(false);
  const [saved, setSaved] = useState<SavedMinutes[]>([]);
  const [showSettings, setShowSettings] = useState(false);
  const [consentAsking, setConsentAsking] = useState(false);
  const [accessCode, setAccessCode] = useState("");
  const [needsCode, setNeedsCode] = useState(false);
  const [copied, setCopied] = useState("");
  const [googleReady, setGoogleReady] = useState(false);
  const [driveConnected, setDriveConnected] = useState(false);
  const [driveStatus, setDriveStatus] = useState("");

  const listenerRef = useRef<Listener | null>(null);
  const queueRef = useRef<Promise<void>>(Promise.resolve());
  const settingsRef = useRef(settings);
  const moduleIdRef = useRef(moduleId);
  const entriesRef = useRef<Entry[]>([]);
  const accessCodeRef = useRef("");
  const tokenClientRef = useRef<TokenClient | null>(null);
  const driveTokenRef = useRef("");
  const pendingUploadRef = useRef<SavedMinutes | null>(null);
  const uploadRecordRef = useRef<((record: SavedMinutes, token?: string) => Promise<void>) | null>(null);

  const activeModule = useMemo(() => moduleById(moduleId), [moduleId]);

  useEffect(() => {
    settingsRef.current = settings;
  }, [settings]);

  useEffect(() => {
    moduleIdRef.current = moduleId;
  }, [moduleId]);

  useEffect(() => {
    entriesRef.current = entries;
  }, [entries]);

  useEffect(() => {
    accessCodeRef.current = accessCode;
  }, [accessCode]);

  const updateEntry = useCallback((id: string, patch: Partial<Entry>) => {
    setEntries((current) => current.map((entry) => (entry.id === id ? { ...entry, ...patch } : entry)));
  }, []);

  const api = useCallback(async (body: Record<string, unknown>) => {
    const headers: Record<string, string> = { "Content-Type": "application/json" };
    if (accessCodeRef.current) headers["x-earhub-code"] = accessCodeRef.current;

    const response = await fetch("/api/ear-hub", {
      method: "POST",
      headers,
      body: JSON.stringify(body),
    });
    const data = (await response.json().catch(() => ({}))) as { text?: string; error?: string; message?: string };

    if (!response.ok) {
      if (data.error === "access_code_required") setNeedsCode(true);
      throw new Error(data.message ?? "サーバーに接続できませんでした。");
    }
    return typeof data.text === "string" ? data.text : "";
  }, []);

  const context = useCallback((): ModuleContext => ({ settings: settingsRef.current, api }), [api]);

  /** 読み上げの音を自分のマイクが拾わないよう、喋っている間だけ認識を落とす。 */
  const speakSafely = useCallback(async (text: string, lang: LanguageCode) => {
    const listener = listenerRef.current;
    listener?.suspend();
    setSpeaking(true);
    try {
      await speak(text, bcp47(lang));
      // 残響を拾い直さないよう、少し置いてから聞き耳に戻す。
      await delay(250);
    } finally {
      setSpeaking(false);
      listener?.resume();
    }
  }, []);

  const handleFinal = useCallback(
    (text: string) => {
      const id = newId();
      const entry: Entry = { id, at: Date.now(), primary: text, status: "pending" };
      setEntries((current) => [...current, entry]);
      setInterim("");

      // 会話の順番が入れ替わらないよう、1件ずつ順に処理する。
      queueRef.current = queueRef.current.then(async () => {
        const earModule = moduleById(moduleIdRef.current);
        try {
          const output = await earModule.onUtterance(text, context());
          if (!output) {
            updateEntry(id, { status: "error", primary: text });
            return;
          }
          updateEntry(id, {
            primary: output.primary,
            secondary: output.secondary,
            highlight: output.highlight,
            status: "done",
          });
          if (output.speak) await speakSafely(output.speak.text, output.speak.lang);
        } catch (cause) {
          updateEntry(id, { status: "error" });
          setError(cause instanceof Error ? cause.message : "処理に失敗しました。");
        }
      });
    },
    [context, speakSafely, updateEntry],
  );

  // localStorage と Web Speech API はサーバー側に存在しないので描画中には読めない。
  // マウント後に一度だけ端末の状態を取り込む。ここだけは意図的に state を書き換える。
  useEffect(() => {
    /* eslint-disable react-hooks/set-state-in-effect */
    setReady(true);
    setSupported(isRecognitionSupported());
    warmUpVoices();
    setSettings(loadSettings());
    setSaved(loadMinutes());
    setAccessCode(loadAccessCode());
    /* eslint-enable react-hooks/set-state-in-effect */
  }, []);

  useEffect(() => {
    const listener = new Listener({
      onFinal: (text) => handleFinal(text),
      onInterim: (text) => setInterim(text),
      onError: (message, fatal) => {
        setError(message);
        if (fatal) setRunning(false);
      },
      onListeningChange: (value) => setListening(value),
    });
    listenerRef.current = listener;
    return () => {
      listener.stop();
      cancelSpeech();
      listenerRef.current = null;
    };
  }, [handleFinal]);

  // 言語や向きを変えたら、聞き取る言語をその場で切り替える。
  useEffect(() => {
    if (!running) return;
    listenerRef.current?.setLang(bcp47(activeModule.recognitionLang(settings)));
  }, [activeModule, running, settings]);

  const updateSettings = useCallback((patch: Partial<EarHubSettings>) => {
    setSettings((current) => {
      const next = { ...current, ...patch };
      saveSettings(next);
      return next;
    });
  }, []);

  const requestDriveToken = useCallback((prompt: string) => {
    if (!tokenClientRef.current) {
      setDriveStatus("Googleの読み込み中です。数秒おいてもう一度押してください。");
      return;
    }
    tokenClientRef.current.requestAccessToken({ prompt });
  }, []);

  const uploadRecord = useCallback(
    async (record: SavedMinutes, tokenOverride?: string) => {
      const token = tokenOverride || driveTokenRef.current;
      // トークンが無い/切れているときは、認可が返ってきてから同じ記録を上げ直す。
      if (!token) {
        pendingUploadRef.current = record;
        requestDriveToken("consent");
        return;
      }

      const folder = settingsRef.current.driveFolder.trim() || DEFAULT_DRIVE_FOLDER;
      setDriveStatus("Googleドライブへ保存しています…");
      const result = await saveToDrive(
        token,
        folder,
        fileNameFor(record.createdAt),
        buildDocument(record.title, record.summary, record.transcript),
      );

      if (result.status === "needs-token") {
        driveTokenRef.current = "";
        setDriveConnected(false);
        pendingUploadRef.current = record;
        requestDriveToken("");
        return;
      }
      if (result.status === "failed") {
        setDriveStatus(result.message);
        return;
      }
      setSaved(saveMinutes({ ...record, driveLink: result.link }));
      setDriveStatus(`「${folder}」に保存しました。`);
    },
    [requestDriveToken],
  );

  useEffect(() => {
    uploadRecordRef.current = uploadRecord;
  }, [uploadRecord]);

  useEffect(() => {
    if (!googleReady || !GOOGLE_CLIENT_ID) return;
    tokenClientRef.current = initTokenClient((response) => {
      if (response.error || !response.access_token) {
        pendingUploadRef.current = null;
        setDriveStatus(response.error_description || "Googleドライブへの接続をキャンセルしました。");
        return;
      }
      driveTokenRef.current = response.access_token;
      setDriveConnected(true);
      const pending = pendingUploadRef.current;
      pendingUploadRef.current = null;
      if (pending) void uploadRecordRef.current?.(pending, response.access_token);
      else setDriveStatus("Googleドライブに接続しました。");
    });
  }, [googleReady]);

  const beginSession = useCallback(() => {
    setError("");
    setSummary(null);
    setEntries([]);
    setInterim("");
    // iOSは画面操作を起点にしないと読み上げできないので、開始の瞬間に解錠しておく。
    primeSpeech();
    listenerRef.current?.start(bcp47(activeModule.recognitionLang(settingsRef.current)));
    setRunning(true);
  }, [activeModule]);

  const handleStart = useCallback(() => {
    if (activeModule.requiresConsent) {
      setConsentAsking(true);
      return;
    }
    beginSession();
  }, [activeModule, beginSession]);

  const finishSession = useCallback(async () => {
    listenerRef.current?.stop();
    cancelSpeech();
    setRunning(false);
    setInterim("");

    // 走っている翻訳や読み上げが終わるのを待ってから、まとめに入る。
    await queueRef.current;

    const earModule = moduleById(moduleIdRef.current);
    if (!earModule.onSessionEnd) return;

    const lines = entriesRef.current.filter((entry) => entry.status === "done").map((entry) => entry.primary);
    if (lines.length === 0) return;

    const createdAt = Date.now();
    let summaryBody = "";
    setSummarizing(true);
    try {
      const result = await earModule.onSessionEnd(lines, context());
      if (result) {
        summaryBody = result.body;
        setSummary(result);
      }
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "まとめに失敗しました。");
    } finally {
      setSummarizing(false);
    }

    // 要約に失敗しても、文字起こしそのものは残す。
    const record: SavedMinutes = {
      id: newId(),
      title: `${earModule.name} ${dateOf(createdAt)}`,
      createdAt,
      transcript: lines.join("\n"),
      summary: summaryBody,
    };
    setSaved(saveMinutes(record));

    if (settingsRef.current.driveEnabled && GOOGLE_CLIENT_ID) {
      await uploadRecordRef.current?.(record);
    }
  }, [context]);

  const handleSelectModule = useCallback(
    async (id: ModuleId) => {
      if (id === moduleIdRef.current) return;
      if (running) await finishSession();
      setModuleId(id);
      setEntries([]);
      setInterim("");
      setError("");
      setSummary(null);
    },
    [finishSession, running],
  );

  const copyText = useCallback(async (label: string, text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(label);
      setTimeout(() => setCopied(""), 2000);
    } catch {
      setError("コピーできませんでした。");
    }
  }, []);

  const latest = entries.length > 0 ? entries[entries.length - 1] : null;
  const history = entries.slice(0, -1).reverse();

  const statusLabel = !running
    ? "待機中"
    : speaking
      ? "読み上げ中"
      : listening
        ? "聞いています"
        : "マイク準備中";

  return (
    <main className={styles.page}>
      {GOOGLE_CLIENT_ID ? (
        <Script
          src="https://accounts.google.com/gsi/client"
          strategy="afterInteractive"
          onLoad={() => setGoogleReady(true)}
        />
      ) : null}

      <header className={styles.header}>
        <Link href="https://tools.hitobito.jp/" className={styles.brand}>
          <span>hitobito</span> Tools
        </Link>
        <Link href="https://tools.hitobito.jp/" className={styles.back}>
          TOOLS ↗
        </Link>
      </header>

      <div className={styles.shell}>
        <section className={styles.intro}>
          <p className={styles.eyebrow}>EAR HUB / スマホがセントラル</p>
          <h1 className={styles.title}>いま持っているイヤホンに、機能を足す。</h1>
          <p className={styles.lead}>
            イヤホンは買い替えません。聞く・訳す・記録するの頭脳はスマホ側に置いて、モジュールを選ぶだけで耳の機能が増えます。
          </p>
        </section>

        <section className={styles.modules} aria-label="モジュールを選ぶ">
          {MODULES.map((item) => (
            <button
              key={item.id}
              type="button"
              className={`${styles.moduleCard} ${item.id === moduleId ? styles.moduleCardActive : ""}`}
              onClick={() => handleSelectModule(item.id)}
              aria-pressed={item.id === moduleId}
            >
              <span className={styles.moduleIcon} aria-hidden="true">
                {item.icon}
              </span>
              <span className={styles.moduleName}>{item.name}</span>
              <span className={styles.moduleTagline}>{item.tagline}</span>
              <span className={styles.moduleCost}>{item.usesApi ? "API利用あり" : "端末内で完結"}</span>
            </button>
          ))}
        </section>

        {ready && !supported ? (
          <p className={styles.warning}>
            このブラウザは音声認識(Web Speech API)に対応していません。AndroidのChrome、またはiOSのSafariでお試しください。
          </p>
        ) : null}

        <section className={styles.console} aria-live="polite">
          <div className={styles.consoleTop}>
            <span className={`${styles.status} ${running ? styles.statusOn : ""}`}>{statusLabel}</span>
            <span className={styles.langBadge}>聞き取り: {labelOf(activeModule.recognitionLang(settings))}</span>
          </div>

          <p className={styles.hint}>{activeModule.hint(settings)}</p>

          {moduleId === "translate" ? (
            <div className={styles.directionRow} role="group" aria-label="翻訳の向き">
              <button
                type="button"
                className={`${styles.directionButton} ${settings.direction === "toMe" ? styles.directionActive : ""}`}
                onClick={() => updateSettings({ direction: "toMe" })}
              >
                相手 → 自分の耳
              </button>
              <button
                type="button"
                className={`${styles.directionButton} ${
                  settings.direction === "toPartner" ? styles.directionActive : ""
                }`}
                onClick={() => updateSettings({ direction: "toPartner" })}
              >
                自分 → 相手の画面
              </button>
            </div>
          ) : null}

          <div className={styles.stage}>
            {latest ? (
              <p className={`${styles.stagePrimary} ${latest.highlight ? styles.stageHighlight : ""}`}>
                {latest.status === "pending" && activeModule.usesApi ? "…" : latest.primary}
              </p>
            ) : (
              <p className={styles.stageEmpty}>{running ? "話しかけてください。" : "「開始」を押すと聞き取りが始まります。"}</p>
            )}
            {latest?.secondary ? <p className={styles.stageSecondary}>{latest.secondary}</p> : null}
            {interim ? <p className={styles.interim}>{interim}</p> : null}
          </div>

          <button
            type="button"
            className={`${styles.mainButton} ${running ? styles.mainButtonStop : ""}`}
            onClick={running ? finishSession : handleStart}
            disabled={!supported || summarizing}
          >
            {running ? "停止" : summarizing ? "まとめています…" : "開始"}
          </button>

          {error ? <p className={styles.error}>{error}</p> : null}
        </section>

        {consentAsking ? (
          <section className={styles.consent}>
            <h2>録る前に、ひとこと。</h2>
            <p>
              このモジュールは同席者の発言も文字起こしします。始める前に「記録を取ります」と伝えてください。文字起こしはこの端末の中だけに保存されます。
            </p>
            <div className={styles.consentButtons}>
              <button
                type="button"
                className={styles.primaryButton}
                onClick={() => {
                  setConsentAsking(false);
                  beginSession();
                }}
              >
                伝えた・開始する
              </button>
              <button type="button" className={styles.ghostButton} onClick={() => setConsentAsking(false)}>
                やめる
              </button>
            </div>
          </section>
        ) : null}

        {needsCode ? (
          <section className={styles.consent}>
            <h2>アクセスコード</h2>
            <p>このサーバーはアクセスコードを求めています。コードを入れると、この端末に保存されます。</p>
            <input
              className={styles.input}
              type="password"
              value={accessCode}
              onChange={(event) => setAccessCode(event.target.value)}
              placeholder="アクセスコード"
            />
            <div className={styles.consentButtons}>
              <button
                type="button"
                className={styles.primaryButton}
                onClick={() => {
                  saveAccessCode(accessCode);
                  setNeedsCode(false);
                  setError("");
                }}
              >
                保存する
              </button>
            </div>
          </section>
        ) : null}

        {summarizing ? <p className={styles.notice}>会話をまとめています。少しお待ちください。</p> : null}
        {!summarizing && driveStatus ? <p className={styles.notice}>{driveStatus}</p> : null}

        {summary ? (
          <section className={styles.summary}>
            <div className={styles.summaryTop}>
              <h2>{summary.heading}</h2>
              <button type="button" className={styles.ghostButton} onClick={() => copyText("summary", summary.body)}>
                {copied === "summary" ? "コピーしました" : "コピー"}
              </button>
            </div>
            <div className={styles.summaryBody}>
              {parseSections(summary.body).map((section, index) => (
                <div key={`${section.heading}-${index}`} className={styles.summarySection}>
                  {section.heading ? <h3>{section.heading}</h3> : null}
                  {section.body ? <p>{section.body}</p> : null}
                </div>
              ))}
            </div>
          </section>
        ) : null}

        {history.length > 0 ? (
          <section className={styles.log}>
            <h2 className={styles.sectionTitle}>この回のログ</h2>
            <ul className={styles.logList}>
              {history.map((entry) => (
                <li key={entry.id} className={`${styles.logItem} ${entry.highlight ? styles.logHighlight : ""}`}>
                  <span className={styles.logTime}>{clockOf(entry.at)}</span>
                  <span className={styles.logBody}>
                    <span className={styles.logPrimary}>
                      {entry.status === "error" ? `${entry.primary}(処理できませんでした)` : entry.primary}
                    </span>
                    {entry.secondary ? <span className={styles.logSecondary}>{entry.secondary}</span> : null}
                  </span>
                </li>
              ))}
            </ul>
          </section>
        ) : null}

        <section className={styles.settings}>
          <button type="button" className={styles.settingsToggle} onClick={() => setShowSettings((v) => !v)}>
            設定 {showSettings ? "▲" : "▼"}
          </button>
          {showSettings ? (
            <div className={styles.settingsBody}>
              <label className={styles.field}>
                <span>自分の言語</span>
                <select
                  value={settings.myLang}
                  onChange={(event) => updateSettings({ myLang: event.target.value as LanguageCode })}
                >
                  {LANGUAGE_CODES.map((code) => (
                    <option key={code} value={code}>
                      {LANGUAGES[code].label}
                    </option>
                  ))}
                </select>
              </label>

              <label className={styles.field}>
                <span>相手の言語</span>
                <select
                  value={settings.partnerLang}
                  onChange={(event) => updateSettings({ partnerLang: event.target.value as LanguageCode })}
                >
                  {LANGUAGE_CODES.map((code) => (
                    <option key={code} value={code}>
                      {LANGUAGES[code].label}
                    </option>
                  ))}
                </select>
              </label>

              <label className={styles.checkboxField}>
                <input
                  type="checkbox"
                  checked={settings.speakToPartner}
                  onChange={(event) => updateSettings({ speakToPartner: event.target.checked })}
                />
                <span>
                  相手向けの訳も読み上げる
                  <em>イヤホンを外してスピーカーで会話するときに使います。</em>
                </span>
              </label>

              <label className={styles.field}>
                <span>ウォッチワード</span>
                <input
                  className={styles.input}
                  type="text"
                  value={settings.watchwords}
                  onChange={(event) => updateSettings({ watchwords: event.target.value })}
                  placeholder="予算, 締め切り"
                />
              </label>

              <div className={styles.driveBlock}>
                <p className={styles.driveTitle}>議事録の保存先</p>
                <p className={styles.driveNote}>
                  既定ではこの端末の中だけに残ります。下をONにすると、止めた直後に自分のGoogleドライブへもMarkdownで書き出します。
                </p>

                <label className={styles.checkboxField}>
                  <input
                    type="checkbox"
                    checked={settings.driveEnabled}
                    disabled={!GOOGLE_CLIENT_ID}
                    onChange={(event) => updateSettings({ driveEnabled: event.target.checked })}
                  />
                  <span>
                    Googleドライブにも保存する
                    {GOOGLE_CLIENT_ID ? null : <em>この環境ではGoogle連携が設定されていません。</em>}
                  </span>
                </label>

                <label className={styles.field}>
                  <span>保存先フォルダ名</span>
                  <input
                    className={styles.input}
                    type="text"
                    value={settings.driveFolder}
                    onChange={(event) => updateSettings({ driveFolder: event.target.value })}
                    placeholder={DEFAULT_DRIVE_FOLDER}
                  />
                </label>

                <div className={styles.driveRow}>
                  <button
                    type="button"
                    className={styles.ghostButton}
                    disabled={!GOOGLE_CLIENT_ID}
                    onClick={() => requestDriveToken(driveConnected ? "" : "consent")}
                  >
                    {driveConnected ? "Googleを接続し直す" : "Googleに接続"}
                  </button>
                  {driveStatus ? <span className={styles.driveStatus}>{driveStatus}</span> : null}
                </div>

                <p className={styles.driveNote}>
                  求める権限は drive.file
                  だけです。このアプリが作ったファイル以外は読み書きできません。作られたフォルダはドライブ側で移動・改名しても、そのまま保存先として使われます。
                </p>
              </div>
            </div>
          ) : null}
        </section>

        {saved.length > 0 ? (
          <section className={styles.saved}>
            <h2 className={styles.sectionTitle}>保存した記録</h2>
            <ul className={styles.savedList}>
              {saved.map((item) => (
                <li key={item.id} className={styles.savedItem}>
                  <div className={styles.savedTop}>
                    <span className={styles.savedTitle}>{item.title}</span>
                    <span className={styles.savedActions}>
                      <button
                        type="button"
                        className={styles.ghostButton}
                        onClick={() => copyText(item.id, item.summary || item.transcript)}
                      >
                        {copied === item.id ? "コピーしました" : "コピー"}
                      </button>
                      {item.driveLink ? (
                        <a
                          className={styles.ghostButton}
                          href={item.driveLink}
                          target="_blank"
                          rel="noreferrer"
                        >
                          ドライブで開く
                        </a>
                      ) : GOOGLE_CLIENT_ID ? (
                        <button
                          type="button"
                          className={styles.ghostButton}
                          onClick={() => void uploadRecord(item)}
                        >
                          ドライブに保存
                        </button>
                      ) : null}
                      <button
                        type="button"
                        className={styles.ghostButton}
                        onClick={() => setSaved(deleteMinutes(item.id))}
                      >
                        削除
                      </button>
                    </span>
                  </div>
                  <p className={styles.savedPreview}>{previewOf(item.summary || item.transcript)}</p>
                </li>
              ))}
            </ul>
          </section>
        ) : null}

        <footer className={styles.footnote}>
          <p>
            音声認識と読み上げは端末のブラウザ機能を使うので、通信量以外の費用はかかりません。Claude
            APIを呼ぶのは、翻訳の1発話ごとと、議事録をまとめる1回だけです。
          </p>
          <p>
            会話も議事録もこの端末の中(localStorage)に保存され、こちらのサーバーには残りません。端末の外に出すのは、設定でGoogleドライブ保存をONにしたときだけです。
          </p>
        </footer>
      </div>
    </main>
  );
}

"use client";

import Link from "next/link";
import { useLayoutEffect, useMemo, useState } from "react";
import EarHub from "./EarHub";
import { MODULES, moduleById, type ModuleId } from "./modules";
import styles from "./ear-hub-store.module.css";

type Props = {
  moduleId: ModuleId;
};

export default function EarHubLauncher({ moduleId }: Props) {
  const activeModule = useMemo(() => moduleById(moduleId), [moduleId]);
  const [ready, setReady] = useState(moduleId === "translate");

  useLayoutEffect(() => {
    const moduleIndex = MODULES.findIndex((item) => item.id === moduleId);
    const moduleButtons = Array.from(
      document.querySelectorAll<HTMLButtonElement>('section[aria-label="モジュールを選ぶ"] button'),
    );

    if (moduleIndex >= 0 && moduleId !== "translate") {
      moduleButtons[moduleIndex]?.click();
    }

    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, [moduleId]);

  return (
    <div className={styles.appFrame}>
      <header className={styles.appBar}>
        <Link href="/ear-hub" className={styles.appBack}>
          ‹ DIGIL CLOUD
        </Link>
        <div className={styles.appBarTitle}>
          <span className={styles.appBarIcon} aria-hidden="true">{activeModule.icon}</span>
          <span>{activeModule.name}</span>
        </div>
        <span className={styles.appBarSpacer} aria-hidden="true" />
      </header>

      <div className={`${styles.embedded} ${ready ? styles.embeddedReady : ""}`}>
        <EarHub />
      </div>
    </div>
  );
}
